import{_ as t,o,c as r,a2 as i}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Competitive Intelligence — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"competitive-intel-02-how-tos-and-workflows.md","filePath":"competitive-intel-02-how-tos-and-workflows.md"}'),a={name:"competitive-intel-02-how-tos-and-workflows.md"};function n(s,e,l,d,p,c){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="competitive-intelligence-—-how-tos-workflows" tabindex="-1">Competitive Intelligence — How-tos &amp; Workflows <a class="header-anchor" href="#competitive-intelligence-—-how-tos-workflows" aria-label="Permalink to &quot;Competitive Intelligence — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Competitive Intelligence workflows</em></p><hr><h2 id="adding-a-competitor" tabindex="-1">Adding a Competitor <a class="header-anchor" href="#adding-a-competitor" aria-label="Permalink to &quot;Adding a Competitor&quot;">​</a></h2><p>Competitors can be added manually or suggested by AI.</p><h3 id="option-a-add-manually" tabindex="-1">Option A: Add manually <a class="header-anchor" href="#option-a-add-manually" aria-label="Permalink to &quot;Option A: Add manually&quot;">​</a></h3><ol><li>Navigate to <strong>Intel</strong> in the left-hand navigation.</li><li>Click <strong>Add Competitor</strong>.</li><li>Enter the competitor&#39;s name (required) and website (optional).</li><li>Save. The competitor appears in your competitor list.</li></ol><h3 id="option-b-use-ai-suggestions" tabindex="-1">Option B: Use AI suggestions <a class="header-anchor" href="#option-b-use-ai-suggestions" aria-label="Permalink to &quot;Option B: Use AI suggestions&quot;">​</a></h3><p>If you&#39;re not sure who your main competitors are, or want to make sure you haven&#39;t missed anyone:</p><ol><li>Navigate to <strong>Intel</strong>.</li><li>Click <strong>Suggest Competitors</strong> (the AI icon button).</li><li>Lodestone uses your industry description to generate a list of likely competitors.</li><li>Review the suggestions. Select the ones you want to track.</li><li>Click <strong>Add Selected</strong>. The selected competitors are added to your list.</li></ol><blockquote><p><strong>Note:</strong> AI suggestions are based on your industry description. If suggestions feel off-target, update your industry description in the Competitive Intelligence settings first.</p></blockquote><hr><h2 id="removing-a-competitor" tabindex="-1">Removing a Competitor <a class="header-anchor" href="#removing-a-competitor" aria-label="Permalink to &quot;Removing a Competitor&quot;">​</a></h2><ol><li>Navigate to <strong>Intel</strong>.</li><li>Find the competitor you want to remove in the competitor list.</li><li>Click the delete icon next to their name.</li></ol><p>Removing a competitor does not delete any previously generated reports. Existing reports remain accessible; future reports will simply not include the removed competitor.</p><hr><h2 id="generating-a-report" tabindex="-1">Generating a Report <a class="header-anchor" href="#generating-a-report" aria-label="Permalink to &quot;Generating a Report&quot;">​</a></h2><p>You can generate a report at any time, regardless of your automatic schedule.</p><ol><li>Navigate to <strong>Intel</strong>.</li><li>Click <strong>Generate Report</strong>.</li><li>The report generation begins. A new entry appears in your reports list with a <strong>Generating</strong> status.</li><li>Generation typically takes a few minutes. When complete, the status updates to <strong>Completed</strong> and the report becomes readable.</li></ol><blockquote><p><strong>Note:</strong> Report generation requires at least one competitor to be in your list. If the competitor list is empty, the Generate Report button is disabled.</p></blockquote><hr><h2 id="reading-a-report" tabindex="-1">Reading a Report <a class="header-anchor" href="#reading-a-report" aria-label="Permalink to &quot;Reading a Report&quot;">​</a></h2><ol><li>Navigate to <strong>Intel</strong>.</li><li>Click on any completed report in the reports list.</li><li>The full report opens, displaying the AI-generated analysis as formatted text.</li><li>Use the back link to return to the reports list.</li></ol><hr><h2 id="downloading-a-report-as-pdf" tabindex="-1">Downloading a Report as PDF <a class="header-anchor" href="#downloading-a-report-as-pdf" aria-label="Permalink to &quot;Downloading a Report as PDF&quot;">​</a></h2><ol><li>Open a completed report.</li><li>Click <strong>Download PDF</strong>.</li><li>The report downloads as a PDF file, ready to share or archive.</li></ol><blockquote><p><strong>Note:</strong> PDF download is only available for completed reports. Reports with a Generating or Failed status cannot be downloaded.</p></blockquote><hr><h2 id="extracting-features-from-a-report" tabindex="-1">Extracting Features from a Report <a class="header-anchor" href="#extracting-features-from-a-report" aria-label="Permalink to &quot;Extracting Features from a Report&quot;">​</a></h2><p>Once a report is completed, you can send it to the Extracts module to surface product ideas from the competitive analysis.</p><ol><li>Open a completed report.</li><li>Click <strong>Extract Features from Report</strong>.</li><li>You are redirected to the Extracts module, where the AI analyzes the report and surfaces ideas as extract cards.</li><li>Review the extracts as you would any other extract — add ideas to your backlog or dismiss them.</li></ol><p>Extracts sourced from a competitive intelligence report carry an <strong>Intel Report</strong> badge, distinguishing them from transcript-sourced ideas.</p><hr><h2 id="configuring-the-report-schedule" tabindex="-1">Configuring the Report Schedule <a class="header-anchor" href="#configuring-the-report-schedule" aria-label="Permalink to &quot;Configuring the Report Schedule&quot;">​</a></h2><ol><li>Navigate to <strong>Intel</strong>.</li><li>Click <strong>Settings</strong> (the gear icon).</li><li>Set your preferred <strong>Report Frequency</strong>: Weekly or Biweekly.</li><li>Set the <strong>Day of the week</strong> when reports should be generated.</li><li>Update your <strong>Industry Description</strong> (see below).</li><li>Save. Reports will now be generated automatically on your schedule.</li></ol><hr><h2 id="writing-your-industry-description" tabindex="-1">Writing Your Industry Description <a class="header-anchor" href="#writing-your-industry-description" aria-label="Permalink to &quot;Writing Your Industry Description&quot;">​</a></h2><p>The industry description is the context the AI uses when analyzing your competitors. It is distinct from the Organization Description used elsewhere in Lodestone.</p><p>A strong industry description should cover:</p><ul><li>The market or industry you compete in</li><li>The type of product you make</li><li>Who your customers are</li><li>Any context that defines the competitive landscape</li></ul><blockquote><p><strong>Example:</strong> &quot;We build product management software for B2B SaaS product teams. Our competitors include both dedicated PM tools and broader project management platforms that have added PM features.&quot;</p></blockquote><hr><p><em>Next: Advanced Features &amp; Customization — report scheduling strategy, AI suggestion tips, and connecting reports to your planning workflow.</em></p>',43)])])}const h=t(a,[["render",n]]);export{g as __pageData,h as default};
